import collections
def transform(grid):
    h=len(grid);w=len(grid[0]);H,W=h//3,w//3
    out=[[0]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            c=collections.Counter()
            for a in range(3*i,3*i+3):
                for b in range(3*j,3*j+3):
                    v=grid[a][b]
                    if v!=5: c[v]+=1
            out[i][j]=c.most_common(1)[0][0] if c else 5
    return out

